/**
 * Every model call through a Cloudflare AI Gateway (owner, DECISIONS 156 addendum, 10 October 2026), with the binding
 * rules intact: no gateway cache (a cached answer is not a model call), no gateway retries or fallbacks (the site's own
 * retry rules stay the only ones) and no stored request or response bodies in gateway logs (metadata only).
 *
 * The route (coordinator, 10 October 2026): the account's existing gateway (id from the Worker variable `AI_GATEWAY_ID`,
 * `default` on the owner's site, shared with the owner's other Workers) through the Worker's `AI` binding. HTTP vendors
 * go through `env.AI.gateway(id).run({ provider, endpoint, headers, query })`, which returns the provider's `Response`
 * (Workers types generated by wrangler 4.149, `AiGateway.run(...): Promise<Response>`) and is pre-authenticated, so no
 * gateway token or account id is needed (ai-gateway/configuration/authentication/: binding requests are pre-authenticated).
 * The Workers AI reader passes `gateway: {...}` to `env.AI.run`. Because the gateway is shared, nothing relies on its
 * own settings: every request carries this site's controls (`cf-aig-skip-cache`, `cf-aig-collect-log-payload: false`,
 * `cf-aig-max-attempts: 1`, `cf-aig-request-timeout`, `cf-aig-no-wholesale`) and `metadata: { caller: "doc-classifier" }`.
 *
 * Verified 10 October 2026 (HANDOFF): provider paths (the provider base replaces `https://api.openai.com/v1`,
 * `https://api.anthropic.com` and `https://api.deepseek.com`), the per-request headers, the binding's gateway options.
 * Not documented on this path: custom providers, so TypeSafe (Jev) stays direct (`direct` route, chosen by vendor, never
 * because a setting is missing); and the universal call's pass-through of a provider's error status and body, which the
 * first live call shows (a gateway envelope is caught as the gateway's own refusal either way).
 *
 * A missing gateway setting is reported (Health, and a blocker before any request); it never falls back to the vendor's
 * own URL. Only a `local` route, which this build chooses only when its vendors are the pretend ones, keeps the vendor URL.
 */
import { ValidationFailure } from './validate.ts';
import { outbound } from './outbound.ts';
import { usageCopy } from '../ui/copy-usage.ts';

/** How this site's calls are told apart in the shared gateway's logs. */
export const GATEWAY_CALLER = 'doc-classifier';
/** The site's own request timeout (core/server/execution.ts), so the gateway never cuts a call shorter. */
export const GATEWAY_REQUEST_TIMEOUT_MS = 10 * 60 * 1000;

/** Each vendor base and the gateway provider that replaces it. Exact prefixes, matched up to a path separator. */
const UPSTREAMS: readonly { readonly base: string; readonly provider: string }[] = Object.freeze([
  Object.freeze({ base: 'https://api.openai.com/v1', provider: 'openai' }),
  Object.freeze({ base: 'https://api.anthropic.com', provider: 'anthropic' }),
  Object.freeze({ base: 'https://api.deepseek.com', provider: 'deepseek' })
]);

/** A request vendor, as core/vendors/requests.ts names them (kept here as text to avoid an import cycle). */
type RouteVendor = 'openai' | 'anthropic' | 'deepseek' | 'cloudflare' | 'typesafe';
/**
 * Where a vendor request goes. `gateway`: through the configured gateway on the `AI` binding (every live model call).
 * `direct`: the vendor URL over the network; TypeSafe only, by vendor (no custom provider is documented on the binding
 * path). `local`: the vendor URL answered in-process by the pretend vendors or a test's injected fetch; production picks
 * it only when the build's outbound is the pretend one.
 */
export type OutboundRoute = { readonly kind: 'gateway'; readonly gatewayId: string; readonly egress?: 'placed-worker' } | { readonly kind: 'direct' } | { readonly kind: 'local' };

/**
 * The placed egress (DECISIONS 156, addendum of 12 October 2026; on the owner's site since that day, wrangler.owner.jsonc;
 * HTTP vendors only: the Workers AI request keeps this Worker's own binding, core/server/workers-ai.ts). The Worker
 * variable `AI_GATEWAY_EGRESS`, when present, must be exactly `placed-worker`: the gateway call is
 * then made by the helper Worker on the service binding `AI_EGRESS` (core/server/ai-egress-worker.ts), whose
 * `placement.region` keeps the call in a data centre the vendors serve (12 October 2026: every Claude call answered from
 * Hong Kong was refused at the edge; Anthropic does not serve Hong Kong). Absent, the call is made on this Worker's own
 * `AI` binding as before. The helper marks each gateway reply it hands back with this header; a reply without it is the
 * helper's or the runtime's own failure, never a vendor's. The mark is removed before the reply is kept.
 */
export const AI_EGRESS_MARKER = 'x-doc-classifier-egress';
interface EgressFetcher { fetch(input: string, init: RequestInit): Promise<Response> }
const egressFetcher = (env: unknown): EgressFetcher | null =>
  record(env) && record(env.AI_EGRESS) && typeof env.AI_EGRESS.fetch === 'function' ? env.AI_EGRESS as unknown as EgressFetcher : null;

const record = (value: unknown): value is Record<string, unknown> => value !== null && typeof value === 'object' && !Array.isArray(value);
const metadata = () => ({ caller: GATEWAY_CALLER });
/** The gateway providers this site sends to (the placed egress helper forwards these and nothing else). */
export const GATEWAY_PROVIDERS: ReadonlySet<string> = new Set(UPSTREAMS.map(upstream => upstream.provider));

/** The gateway provider and provider path of one vendor endpoint. An endpoint with no provider is refused, never sent. */
export function gatewayTarget(endpoint: string): { provider: string; endpoint: string } {
  for (const { base, provider } of UPSTREAMS)
    if (endpoint.startsWith(base + '/') && endpoint.length > base.length + 1) return { provider, endpoint: endpoint.slice(base.length + 1) };
  throw new ValidationFailure('E_AI_GATEWAY_ROUTE', 'blocker', usageCopy.gatewayRoute);
}

/** The controls every HTTP gateway request carries, whatever the shared gateway's own settings are. */
export function gatewayHeaders(): Record<string, string> {
  return {
    'cf-aig-skip-cache': 'true', 'cf-aig-collect-log-payload': 'false', 'cf-aig-max-attempts': '1',
    'cf-aig-request-timeout': String(GATEWAY_REQUEST_TIMEOUT_MS), 'cf-aig-no-wholesale': 'true',
    'cf-aig-metadata': JSON.stringify(metadata())
  };
}

/** The same controls as the binding's own gateway options for the universal call (Workers types `UniversalGatewayOptions`). */
export function universalGatewayOptions(): { skipCache: true; retries: { maxAttempts: 1 }; requestTimeoutMs: number; metadata: { caller: string } } {
  return { skipCache: true, retries: { maxAttempts: 1 }, requestTimeoutMs: GATEWAY_REQUEST_TIMEOUT_MS, metadata: metadata() };
}

/**
 * The Workers AI binding's gateway option. The binding documents `id`, `skipCache`, `cacheTtl`, `cacheKey`, `collectLog`
 * and `metadata` (ai-gateway/usage/worker-binding-methods/); its types add `retries` and `requestTimeoutMs`. It documents
 * no payload-only log switch, so these requests turn their gateway log off entirely (stricter than metadata-only).
 */
export function workersAiGatewayOptions(gatewayId: string) {
  return { id: gatewayId, skipCache: true as const, collectLog: false as const, retries: { maxAttempts: 1 as const },
    requestTimeoutMs: GATEWAY_REQUEST_TIMEOUT_MS, metadata: metadata() };
}

/** A gateway name: letters, digits, `-` and `_`, starting with a letter or digit, at most 64 characters (AI Gateway limits). */
export const GATEWAY_ID = /^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/;
interface GatewayHandle { run(data: unknown, options?: unknown): Promise<unknown> }
function aiGateway(env: unknown, gatewayId: string): GatewayHandle | null {
  const ai = record(env) ? env.AI : undefined;
  if (!record(ai) || typeof ai.gateway !== 'function') return null;
  const handle: unknown = (ai.gateway as (id: string) => unknown)(gatewayId);
  return record(handle) && typeof handle.run === 'function' ? handle as unknown as GatewayHandle : null;
}

/**
 * The gateway named by the Worker variable `AI_GATEWAY_ID`, reached through the `AI` binding. A missing, empty or
 * placeholder id, or a binding without `gateway()`, is listed by name, never defaulted.
 */
export function readAiGatewayConfig(env: unknown): { gatewayId: string; egress?: 'placed-worker' } | { missing: string[] } {
  const bindings = record(env) ? env : {};
  const missing: string[] = [];
  const gatewayId = bindings.AI_GATEWAY_ID;
  if (typeof gatewayId !== 'string' || !GATEWAY_ID.test(gatewayId)) missing.push('AI_GATEWAY_ID');
  const placed = Object.hasOwn(bindings, 'AI_GATEWAY_EGRESS');
  if (placed && bindings.AI_GATEWAY_EGRESS !== 'placed-worker') missing.push('AI_GATEWAY_EGRESS');
  else if (placed && !egressFetcher(bindings)) missing.push('AI_EGRESS');
  else if (!placed && (!record(bindings.AI) || typeof bindings.AI.gateway !== 'function')) missing.push('AI');
  if (missing.length) return { missing };
  return placed ? { gatewayId: gatewayId as string, egress: 'placed-worker' } : { gatewayId: gatewayId as string };
}

/**
 * This build's route for one vendor: `local` when the build's vendors are the pretend ones (they answer in-process);
 * otherwise `direct` for TypeSafe and the configured gateway for every model call, or a blocker when it is not configured.
 */
export async function siteRoute(env: unknown, vendor: RouteVendor): Promise<OutboundRoute> {
  if (outbound.vendors === 'fake') return { kind: 'local' };
  if (vendor === 'typesafe') return { kind: 'direct' };
  const config = readAiGatewayConfig(env);
  if ('missing' in config) throw new ValidationFailure('E_AI_GATEWAY_CONFIG', 'blocker', usageCopy.gatewayMissing);
  return { kind: 'gateway', ...config };
}

/**
 * Health's view of the route (nothing is sent): null when this build can route every model call, or why it cannot. A
 * pretend build needs no gateway. Never contacts the gateway, so a wrong gateway name still reads READY until its first call.
 */
export async function gatewayIssue(env: unknown): Promise<{ code: 'E_AI_GATEWAY_CONFIG'; headline: string; missing: string[] } | null> {
  if (outbound.vendors === 'fake') return null;
  const config = readAiGatewayConfig(env);
  return 'missing' in config ? { code: 'E_AI_GATEWAY_CONFIG', headline: usageCopy.gatewayMissing, missing: config.missing } : null;
}

/** Statuses whose `Response` cannot carry a body (Fetch standard, "null body status"). */
const NULL_BODY_STATUS = new Set([101, 103, 204, 205, 304]);
/**
 * A reply from the `AI` binding, read whole exactly once and handed on as a `Response` built from those bytes, with the
 * same status, status text and headers. Live incident, 11 October 2026, 07:52 UTC (build 4792a0f): the binding's reply
 * body is a stream with no known length, R2 refuses such a stream ("Provided readable stream must have a known length"),
 * and the first GPT-5.4 run stopped with E_INTERNAL before any call was recorded. Nothing is decoded or changed here: the
 * bytes are the bytes received, and the caller still stores them before anything parses them. Used for the gateway's
 * `.run()` (sendRouted) and the Workers AI binding's raw reply (core/server/workers-ai.ts). A failure while reading the
 * body is the caller's lost connection, like a failure before the reply arrived.
 */
export async function bufferedReply(reply: Response): Promise<Response> {
  const bytes = reply.body === null ? null : new Uint8Array(await reply.arrayBuffer());
  if (NULL_BODY_STATUS.has(reply.status) && bytes !== null && bytes.byteLength > 0)
    throw new ValidationFailure('E_AI_GATEWAY_RESPONSE', 'blocker', usageCopy.gatewayResponse);
  return new Response(NULL_BODY_STATUS.has(reply.status) ? null : bytes,
    { status: reply.status, statusText: reply.statusText, headers: reply.headers });
}

/**
 * Sends one HTTP vendor request on its route. `direct` and `local`: the vendor URL through the build's one outbound path,
 * the reply returned unread, so the caller keeps the exact bytes first. `gateway`: one universal request (never a list,
 * which would be the gateway's fallback chain) carrying the vendor's own headers, this site's controls and the request
 * body as its `query`; the binding must hand back a `Response`, which is read whole once (bufferedReply), so what the
 * caller stores is bytes of known length, never the binding's stream.
 */
export async function sendRouted(env: unknown, route: OutboundRoute, url: string, init: RequestInit): Promise<Response> {
  if (route.kind !== 'gateway') return outbound.fetch(url, init);
  const placed = route.egress === 'placed-worker' ? egressFetcher(env) : null;
  const handle = route.egress === 'placed-worker' ? null : aiGateway(env, route.gatewayId);
  if (!placed && !handle) throw new ValidationFailure('E_AI_GATEWAY_CONFIG', 'blocker', usageCopy.gatewayMissing);
  const target = gatewayTarget(url);
  if (typeof init.body !== 'string') throw new ValidationFailure('E_AI_GATEWAY_ROUTE', 'blocker', usageCopy.gatewayRoute);
  const headers = Object.fromEntries(new Headers(init.headers).entries());
  const data = { provider: target.provider, endpoint: target.endpoint, headers: { ...headers, ...gatewayHeaders() }, query: JSON.parse(init.body) };
  if (placed) {
    // The same one request, sent by the helper on its own `AI` binding; the caller's cancellation cancels this subrequest.
    const reply = await placed.fetch('https://ai-egress.invalid/run', { method: 'POST', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ gatewayId: route.gatewayId, data, options: { gateway: universalGatewayOptions() } }), ...(init.signal ? { signal: init.signal } : {}) });
    if (!(reply instanceof Response) || reply.headers.get(AI_EGRESS_MARKER) !== 'gateway-reply')
      throw new ValidationFailure('E_AI_GATEWAY_RESPONSE', 'blocker', usageCopy.gatewayResponse);
    const kept = new Headers(reply.headers); kept.delete(AI_EGRESS_MARKER);
    return bufferedReply(new Response(reply.body, { status: reply.status, statusText: reply.statusText, headers: kept }));
  }
  const reply = await handle!.run(data, { gateway: universalGatewayOptions(), ...(init.signal ? { signal: init.signal } : {}) });
  if (!(reply instanceof Response)) throw new ValidationFailure('E_AI_GATEWAY_RESPONSE', 'blocker', usageCopy.gatewayResponse);
  return bufferedReply(reply);
}

/**
 * Whether a reply body is the gateway's own error rather than a vendor's: the Cloudflare envelope (`success: false` with
 * an `error` or `errors` list) and no usage. No vendor this site sends through the gateway answers in that shape (OpenAI,
 * DeepSeek and Anthropic put one `error` object in their errors). Read only for HTTP vendors: the Workers AI binding's
 * own errors share the envelope and keep their handling (core/vendors/transport.ts).
 */
export function gatewayEnvelope(body: unknown): boolean {
  return record(body) && body.success === false && (Array.isArray(body.error) || Array.isArray(body.errors)) && !Object.hasOwn(body, 'usage');
}

/** A reply the gateway served from its cache. The request asks it to skip the cache, so this means the gateway ignored that. */
export function gatewayCacheHit(headers: Headers): boolean {
  return (headers.get('cf-aig-cache-status') ?? '').trim().toUpperCase() === 'HIT';
}

/** The vendors an edge refusal is recognised for: those whose own error body format is published (see edgeRefusal). */
const EDGE_VENDORS: Readonly<Record<string, { readonly headerPrefix: string; readonly format: (body: Record<string, unknown>) => boolean }>> = Object.freeze({
  // Anthropic's errors (claude-api reference, read 11 October 2026): {"type":"error","error":{"type":…,"message":…},
  // "request_id":…}. Its format: `type` exactly "error" and an `error` object whose `type` and `message` are strings.
  anthropic: Object.freeze({ headerPrefix: 'anthropic-', format: (body: Record<string, unknown>) => body.type === 'error' &&
    record(body.error) && typeof body.error.type === 'string' && typeof body.error.message === 'string' }),
  // OpenAI's errors: {"error":{"message":…,"type":…,"param":…,"code":…}}, every key present, `param` and `code` a string or
  // null. Its format: an `error` object with string `message` and `type` and both `param` and `code` present as such.
  openai: Object.freeze({ headerPrefix: 'openai-', format: (body: Record<string, unknown>) => record(body.error) &&
    typeof body.error.message === 'string' && typeof body.error.type === 'string' &&
    Object.hasOwn(body.error, 'param') && (body.error.param === null || typeof body.error.param === 'string') &&
    Object.hasOwn(body.error, 'code') && (body.error.code === null || typeof body.error.code === 'string') })
});

/**
 * An edge refusal (DECISIONS 156, addendum of 11 October 2026, owner, "Fail that document only"): a reply to a request sent
 * through the AI Gateway that the AI service's own network turned away before the vendor's API saw it. Batch 9's 403
 * (run 2fe49eed) is the case: `{"error":{"type":"forbidden","message":"Request not allowed"}}` in Cloudflare block-page
 * headers, with none of Anthropic's headers. Pure; the caller passes only replies that came back on the gateway route,
 * the retained raw body unchanged (null when there was none) and the reply's headers. True only when every part holds:
 * - the vendor is Anthropic or OpenAI, whose error formats are published. DeepSeek publishes no error body format, so a
 *   DeepSeek reply is never read as one (it keeps its earlier reading); Workers AI is a binding and TypeSafe goes direct;
 * - the status is a refusal (a 4xx other than 408, 409 and 429) and not 401 (always the key: E_VENDOR_AUTH), 402 (a
 *   balance: E_VENDOR_BALANCE) or 404 (the model: E_MODEL_REJECTED);
 * - the body is not the AI Gateway's own envelope (that is the gateway's refusal, E_AI_GATEWAY_REFUSED, named first), has
 *   no `usage` field, does not name the model (`model_not_found`, `param: "model"`, Anthropic's `model:` message) and is
 *   not in the vendor's own error format (EDGE_VENDORS above). A body that is not a JSON object, or is empty, is not;
 * - the reply carries no vendor request id: no `request-id` or `x-request-id` header, no header starting with the
 *   vendor's own prefix (`anthropic-` or `openai-`), and no string `request_id` in the body. The gateway's own headers
 *   (`cf-aig-*`, `cf-ai-req-id`) and Cloudflare's (`cf-ray`, `server`) are not the vendor's.
 * Anything else keeps its earlier reading. Whether an edge refusal is recorded at zero and fails only its document is the
 * spending policy's (core/cost/spend-admission.ts, not-processed-zero-v5 and -v6); under every earlier policy it is not recognised.
 */
export function edgeRefusal(vendor: string, status: number | null, raw: string | null, headers: Headers): boolean {
  const known = Object.hasOwn(EDGE_VENDORS, vendor) ? EDGE_VENDORS[vendor] : undefined;
  if (!known || status === null || status < 400 || status > 499 || [401, 402, 404, 408, 409, 429].includes(status)) return false;
  if (headers.has('request-id') || headers.has('x-request-id')) return false;
  for (const [name] of headers) if (name.toLowerCase().startsWith(known.headerPrefix)) return false;
  let body: unknown = null;
  if (raw !== null && raw.trim() !== '') {
    try { body = JSON.parse(raw); } catch { body = null; /* Not JSON (a block page, a text body): not the vendor's format. */ }
  }
  if (!record(body)) return true;
  if (gatewayEnvelope(body) || Object.hasOwn(body, 'usage') || typeof body.request_id === 'string' || known.format(body)) return false;
  const error = record(body.error) ? body.error : null;
  const namesModel = error !== null && (error.code === 'model_not_found' || error.param === 'model' ||
    error.type === 'not_found_error' && typeof error.message === 'string' && error.message.startsWith('model:'));
  return !namesModel;
}
